import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))+"/out")
from h18 import *
"""Weekly report built from Monthly: started cards join the report (percent, link to the card), a card delivered last week is not delivered again,
the draft follows the card when it is opened, the checks list what is worth a look, notes of cards never appear. Fake test database only."""
R=[]
def ok(n,c): R.append((n,bool(c))); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as pw:
    b=pw.chromium.launch(); ctx=mkctx(b); ctx.clock.set_fixed_time("2026-10-14T10:00:00"); errs=[]
    A=newpage(ctx,errs); signup(A,'Admin','adm@x.com')
    A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(800)
    oc=A.locator('.mdcol[data-mo="2026-10"]'); oc.locator('.mdopen').click(); ta=oc.locator('.mdadd textarea')
    for t in ['Invoice page','Shipped thing','Idle card']:
        ta.fill(t); ta.press('Enter'); A.wait_for_timeout(450)
    A.keyboard.press('Escape'); A.wait_for_timeout(300)
    card=lambda t: oc.locator('.mdcard:has-text("%s")'%t)
    card('Invoice page').locator('select[aria-label="Percent complete"]').select_option('50'); A.wait_for_timeout(300)
    card('Shipped thing').locator('select[aria-label="Percent complete"]').select_option('100'); A.wait_for_timeout(300)
    A.click('#nav button[data-p="sprints"]'); A.click('button:text-is("+ New sprint")'); A.wait_for_timeout(400)
    A.locator('input[aria-label="Sprint end date"]').fill('2026-10-24'); A.wait_for_timeout(300); A.locator('input[aria-label="Sprint start date"]').fill('2026-10-11'); A.wait_for_timeout(500)
    A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(400); A.click('button:has-text("Build report for week of")'); A.wait_for_timeout(1200)
    txt=lambda: A.locator('#pg-reports').inner_text()
    ok('R1 the new report is built at once and says where it came from', 'Report built from' in A.locator('#pg-reports .rnote:not(.rchecks)').first.inner_text())
    ok('R2 a started card is in the report', 'Invoice page' in txt())
    ok('R3 the idle card is not a line', A.locator('#pg-reports .rline:has-text("Idle card")').count()==0)
    ok('R4 the percent of the card is on the line', A.locator('#pg-reports .rline:has-text("Invoice page") select[aria-label="Percent complete"]').input_value()=='50')
    ok('R5 the delivered card is a line at 100%', A.locator('#pg-reports .rline:has-text("Shipped thing") select[aria-label="Percent complete"]').input_value()=='100')
    ok('R6 the line is linked to the card (feature id filled)', A.locator('#pg-reports .rline:has-text("Invoice page") input[aria-label^="Feature id"]').input_value()!='')
    ok('R7 the header counts Monthly cards', 'Monthly cards' in A.locator('#pg-reports .rmeta').inner_text())
    ok('R8 the checks box counts the idle card', 'has not started' in A.locator('#pg-reports .rchecks').inner_text())
    A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(600)
    card('Invoice page').locator('select[aria-label="Percent complete"]').select_option('80'); A.wait_for_timeout(500)
    A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(400); A.locator('#pg-reports .rpcard a.splink').first.click(); A.wait_for_timeout(700)
    A.reload(); A.wait_for_timeout(1500)
    ok('R9 opening the draft again brings the new percent in', A.locator('#pg-reports .rline:has-text("Invoice page") select[aria-label="Percent complete"]').input_value()=='80')
    ln=A.locator('#pg-reports .rline:has-text("Invoice page") .sptext'); ln.fill('Invoice page, PM wording'); ln.press('Tab'); A.wait_for_timeout(400)
    A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(600)
    card('Invoice page').locator('select[aria-label="Percent complete"]').select_option('90'); A.wait_for_timeout(500)
    A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(400)
    A.locator('#pg-reports .rpcard a.splink').first.click(); A.wait_for_timeout(600); A.click('button:text-is("Sync from Sprint, Roadmap & Monthly")'); A.wait_for_timeout(800)
    ok('R10 a line edited by the PM keeps its wording after a sync', A.locator('#pg-reports .rline:has-text("PM wording")').count()==1)
    ctx.clock.set_fixed_time("2026-10-20T10:00:00"); A.reload(); A.wait_for_timeout(1500)
    A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(400); A.click('button:has-text("Build report for week of")'); A.wait_for_timeout(1200)
    ok('R11 week 2 is built too', A.locator('#pg-reports .rline').count()>=1)
    ok('R12 the card delivered last week is not delivered again', A.locator('#pg-reports .rline:has-text("Shipped thing")').count()==0)
    ok('R13 the card still in progress is there at 90%', A.locator('#pg-reports .rline:has-text("Invoice page") select[aria-label="Percent complete"]').input_value()=='90')
    ok('R14 no page errors', errs==[]); print('errors:',errs[:3])
    print(sum(1 for _,c in R if c),'/',len(R))
